package co.edu.rentainmuebles.dao;
import co.edu.rentainmuebles.SoportePostgres;import co.edu.rentainmuebles.dao.jdbc.*;import co.edu.rentainmuebles.model.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.math.*;import java.util.*;
class DaoJdbcTest extends SoportePostgres {
 @Test void claveIdempotenteNoPermiteCambiarImporte(){Reserva r=reservaFutura();pagos.crear(new Pago(null,r,new BigDecimal("100"),null,r.getFechaCreacion(),EstadoPago.APROBADO,"COBRO",null,"misma-clave"));assertThrows(DaoException.class,()->pagos.crear(new Pago(null,r,new BigDecimal("200"),null,r.getFechaCreacion(),EstadoPago.APROBADO,"COBRO",null,"misma-clave")));assertEquals(new BigDecimal("100.00"),pagos.totalPagado(r.getId()));}
 @Test void giroFallidoEnDaoPermiteNuevoIntento(){Reserva r=reservaPagada();Giro fallido=giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.FALLIDO));assertEquals(EstadoGiro.FALLIDO,fallido.getEstado());Giro nuevo=giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.PENDIENTE));assertEquals(EstadoGiro.PENDIENTE,nuevo.getEstado());assertNotEquals(fallido.getId(),nuevo.getId());}
 @Test void limitesNumericosDelNuevoSql(){assertDoesNotThrow(()->new Inmueble(null,propietario,"Casa","Bogotá","Calle 1",null,32767,new BigDecimal("99999999999999.99"),EstadoInmueble.PUBLICADO));assertThrows(IllegalArgumentException.class,()->new Inmueble(null,propietario,"Casa","Bogotá","Calle 1",null,32768,new BigDecimal("10"),EstadoInmueble.PUBLICADO));}
 @Test void especializacionTriple(){Usuario u=usuarios.crear(new Usuario(null,"Tres perfiles","triple@junit.test",cliente.getHashContrasena(),null,true,true,true,true));Usuario leido=usuarios.buscarPorId(u.getId()).orElseThrow();assertEquals(3,leido.getPerfiles().size());assertNotNull(leido.getAdministrador());assertNotNull(leido.getCliente());assertNotNull(leido.getPropietario());}
 @Test void correoNormalizadoUnico(){assertEquals("23505",assertThrows(DaoException.class,()->usuarios.crear(new Usuario(null,"Otro","CLIENTE@JUNIT.TEST",cliente.getHashContrasena(),null,true,false,true,false))).estadoSql());}
 @Test void ciudadesSinTilde(){assertEquals(1,inmuebles.buscar("Bogota",null,null,null,null).size());assertEquals(1,inmuebles.buscar("BOGOTÁ",null,null,null,null).size());}
 @Test void homonimosConIdentificadoresDiferentes(){var a=new CiudadDaoJdbc().listar().stream().filter(c->c.nombre().equals("Cartagena")).toList();assertEquals(2,a.size());assertNotEquals(a.get(0).id(),a.get(1).id());assertThrows(IllegalArgumentException.class,()->new CiudadDaoJdbc().resolver("Cartagena"));assertNotEquals(a.get(0).division().pais().codigoIso2(),a.get(1).division().pais().codigoIso2());}
 @Test void totalDerivadoYSobreCobro(){Reserva r=reservaFutura();pagos.crear(new Pago(null,r,new BigDecimal("100000"),null,r.getFechaCreacion(),MetodoPago.TARJETA));assertEquals(new BigDecimal("100000.00"),pagos.totalPagado(r.getId()));assertThrows(DaoException.class,()->pagos.crear(new Pago(null,r,r.getTotal(),null,r.getFechaCreacion(),MetodoPago.TARJETA)));assertEquals(1,pagos.listar().size());}
 @Test void idempotenciaDeCobro(){Reserva r=reservaFutura();Pago p=new Pago(null,r,r.getTotal(),null,r.getFechaCreacion(),EstadoPago.APROBADO,"COBRO",null,"prueba-clave");assertEquals(pagos.crear(p).getId(),pagos.crear(p).getId());assertEquals(1,pagos.listar().size());}
 @Test void noConfirmaSinCobro(){Reserva r=reservaFutura();assertThrows(DaoException.class,()->reservas.actualizarEstado(r.getId(),EstadoReserva.CONFIRMADA));}
 @Test void transaccionRevierte(){assertThrows(IllegalStateException.class,()->unidad.ejecutar(d->{d.inmuebles().desactivar(inmueble.getId());throw new IllegalStateException();}));assertEquals(EstadoInmueble.PUBLICADO,inmuebles.buscarPorId(inmueble.getId()).orElseThrow().getEstado());}
 @Test void eliminacionDeInmuebleConHistorialRechazada(){reservaFutura();assertThrows(DaoException.class,()->inmuebles.eliminar(inmueble.getId()));}
 @Test void edicionTarifaConservaContrato(){Reserva r=reservaFutura();servicios.inmuebles.editar(propietario.getId(),inmueble.getId(),"Casa actualizada","Bogotá","Calle 10","Descripción",4,new BigDecimal("200000"));assertEquals(new BigDecimal("150000.00"),reservas.buscarPorId(r.getId()).orElseThrow().getPrecioPorNoche());}
}
